Below is an implementation of a sorting algorithm using a max-heap: the **Heap Sort** algorithm. This method is particularly useful for both small data sets and those that cannot fit into memory. 

Heap Sort works by transforming the list into a max-heap, and then repeatedly extracting the maximum element from the heap and placing it at the end of the list. 

Here's the algorithm implemented in Python:

```python
class MaxHeap:
    def __init__(self, arr=None):
        self.heap = []
        if arr:
            self.build_heap(arr)

    def build_heap(self, arr):
        self.heap = arr
        for i in range(len(arr) // 2 - 1, -1, -1):
            self.max_heapify(i)

    def max_heapify(self, index):
        left = 2 * index + 1
        right = 2 * index + 2
        largest = index

        if left < len(self.heap) and self.heap[left] > self.heap[largest]:
            largest = left
        if right < len(self.heap) and self.heap[right] > self.heap[largest]:
            largest = right

        if index != largest:
            self.heap[index], self.heap[largest] = self.heap[largest], self.heap[index]
            self.max_heapify(largest)

    def insert(self, value):
        self.heap.append(value)
        self.max_heapify(len(self.heap) - 1)

    def extract_max(self):
        if len(self.heap) == 0:
            return None
        if len(self.heap) == 1:
            return self.heap.pop()

        root = self.heap[0]
        self.heap[0] = self.heap.pop()
        self.max_heapify(0)
        return root

    def is_empty(self):
        return len(self.heap) == 0

def heap_sort(arr):
    heap = MaxHeap(arr)
    sorted_arr = []
    while not heap.is_empty():
        sorted_arr.append(heap.extract_max())
    return sorted_arr

# Example usage:
arr = [12, 11, 13, 5, 6, 7]
sorted_arr = heap_sort(arr)
print("Sorted array is:", sorted_arr)
